// Naglowek.js
export default function Naglowek(tekst) {
  return `<h1>${tekst}</h1>`;
}

// App.js
import Naglowek from "./Naglowek.js";
console.log(Naglowek("Witaj")); // "<h1>Witaj</h1>"

// Header.js
export default function Header() { return "=== NAGLOWEK ==="; }

// Tresc.js
export default function Tresc() { return "To jest tresc strony."; }

// Stopka.js
export default function Stopka() { return "=== STOPKA ==="; }

// App.js
import Header from "./Header.js";
import Tresc from "./Tresc.js";
import Stopka from "./Stopka.js";

console.log(Header());
console.log(Tresc());
console.log(Stopka());

// Nazwa importu domyslnego jest technicznie DOWOLNA (jak w lekcji 3) -
// import x from './Button.jsx'; zadzialaloby identycznie jak
// import Button from './Button.jsx';
//
// Jednak w praktyce, w PRAWIE KAZDYM projekcie React, nazwa importu
// zgadza sie z nazwa komponentu/pliku - to KONWENCJA, nie wymog jezyka.
// Powod jest czysto praktyczny: gdy ktos czyta kod i widzi
// import Button from './Button.jsx', od razu WIE, co ten import
// reprezentuje. Gdyby uzyto dowolnej, niezwiazanej nazwy (np. 'x'),
// czytelnik musialby przeszukac caly plik, zeby zrozumiec, co ten
// import faktycznie oznacza.

// Ikony.js
export function IkonaDomek() { return "Dom"; }
export function IkonaKoszyk() { return "Koszyk"; }
export function IkonaUzytkownik() { return "Uzytkownik"; }

// App.js
import * as Ikony from "./Ikony.js";
console.log(Ikony.IkonaDomek());      // "Dom"
console.log(Ikony.IkonaKoszyk());     // "Koszyk"
console.log(Ikony.IkonaUzytkownik()); // "Uzytkownik"

// PanelAdmina.js
export default function PanelAdmina() { return "Panel administratora"; }

// App.js
async function ladujPanelAdmina() {
  const modul = await import("./PanelAdmina.js");
  console.log(modul.default()); // "Panel administratora"
}
ladujPanelAdmina();

// Mechanizm React.lazy() opiera sie DOKLADNIE na tym wzorcu - wewnatrz
// wykorzystuje import() dynamiczny do 'leniwego' zaladowania komponentu
// dopiero wtedy, gdy jest on faktycznie potrzebny w interfejsie.
